package validation

import "fyne.io/fyne/v2"

// NewAllStrings returns a StringValidator that runs all provided validators in order.
// It returns the first error encountered, or nil if all validators pass.
//
// Example:
//
//	validator := validation.NewAllStrings(
//		validation.NewRegexp(`^\d+$`, "must contain only digits"),
//		func(s string) error {
//			if len(s) < 5 {
//				return errors.New("must be at least 5 characters")
//			}
//			return nil
//		},
//	)
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(s string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(s); err != nil {
				return err
			}
		}
		return nil
	}
}

package desktop

import "fyne.io/fyne/v2"

// App defines desktop-specific extensions to the fyne.App interface.
//
// Since: 2.2
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the system tray menu for desktop platforms.
	// The menu will appear when the user interacts with the app's system tray icon.
	// Pass nil to remove the system tray menu.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the system tray icon for desktop platforms.
	// The icon will be displayed in the system tray/notification area.
	// Pass nil to remove the system tray icon.
	SetSystemTrayIcon(icon fyne.Resource)
}

